catalog_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below

 alert("Running Client Script");
var ga = new GlideAjax('UpdatingExistingContact');
ga.addParam('sysparm_name','contact');
ga.addParam('sysparm_u_counterparty_code',g_form.getValue('counterparty_code'));
ga.getXML(errorTypeParse);
function errorTypeParse(response) {
answer = response.responseXML.documentElement.getAttribute("answer");
alert(answer+"testContact");
var contactDetails = JSON.decode(answer);
var i = 0;
while(i < contact.length)
{
//g_form.addOption('contact',contact[i].counterparty_code, contact[i].gss_cateogy);
	var counterPartyCode = contact[i].u_counterparty_code;
	var emailAddress = contact[i].account;
	g_form.setValue('counterparty_code',counterPartyCode);
	g_form.setValue('account',emailAddress);
 i++;
 }
 }


	}
